"""Normalize JAR packaging metadata; preserve entry bytes and permission attributes.

Python 3.8+ stdlib only. Class entries are newer than source entries because
Clojure's loader uses a strict timestamp comparison when choosing AOT classes.
"""

import argparse
import datetime
import json
import os
import shutil
import stat
import struct
import tempfile
import zipfile
from pathlib import Path

# ZIP64 is regenerated by the writer; these other fields carry timestamps.
VOLATILE_EXTRA_FIELDS = {0x0001, 0x000A, 0x5455}
# Mixed timestamp/Unix metadata needs a dedicated preservation policy.
UNSUPPORTED_EXTRA_FIELDS = {0x000D, 0x5855}


def stable_extra(data):
    kept = []
    offset = 0
    while offset < len(data):
        if len(data) - offset < 4:
            raise ValueError("Truncated ZIP extra-field header")
        kind, size = struct.unpack_from("<HH", data, offset)
        end = offset + 4 + size
        if end > len(data):
            raise ValueError("Truncated ZIP extra-field payload")
        if kind in UNSUPPORTED_EXTRA_FIELDS:
            raise ValueError(f"Unsupported mixed Unix ZIP extra field: {kind:#06x}")
        if kind not in VOLATILE_EXTRA_FIELDS:
            kept.append(data[offset:end])
        offset = end
    return b"".join(kept)


def zip_date(epoch):
    value = datetime.datetime.fromtimestamp(epoch, datetime.timezone.utc)
    if not 1980 <= value.year <= 2107:
        raise ValueError("JAR timestamps must be within ZIP's 1980–2107 range")
    return (value.year, value.month, value.day, value.hour, value.minute, value.second)


def normalize(source, destination, epoch=315532800):
    source, destination = Path(source), Path(destination)
    # ZIP DOS timestamps have two-second precision. Reserve the next tick for
    # classes, including across day/year boundaries.
    epoch = epoch - epoch % 2
    ordinary, compiled = zip_date(epoch), zip_date(epoch + 2)
    mode = stat.S_IMODE(source.stat().st_mode)
    descriptor, temporary = tempfile.mkstemp(prefix=".jar-", dir=destination.parent)
    count = 0
    try:
        with os.fdopen(descriptor, "wb") as stream, zipfile.ZipFile(source) as original:
            entries = original.infolist()
            names = [entry.filename for entry in entries]
            if len(names) != len(set(names)):
                raise ValueError("Duplicate JAR entry names have ambiguous lookup behavior")
            with zipfile.ZipFile(stream, "w", compression=zipfile.ZIP_DEFLATED,
                                 compresslevel=9) as output:
                output.comment = original.comment
                for entry in sorted(entries, key=lambda item: item.filename):
                    info = zipfile.ZipInfo(
                        entry.filename,
                        compiled if entry.filename.endswith(".class") else ordinary,
                    )
                    info.compress_type = zipfile.ZIP_DEFLATED
                    # open(ZipInfo) does not inherit ZipFile.compresslevel.
                    info._compresslevel = 9
                    info.create_system = entry.create_system
                    info.external_attr = entry.external_attr
                    info.internal_attr = entry.internal_attr
                    info.comment = entry.comment
                    info.extra = stable_extra(entry.extra)
                    info.file_size = entry.file_size
                    with original.open(entry) as src, output.open(info, "w") as dst:
                        shutil.copyfileobj(src, dst, length=1024 * 1024)
                    # ZipFile supplies default permissions for a zero attribute.
                    # Restore the original value in the central directory too.
                    info.external_attr = entry.external_attr
                    count += 1
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, mode)
        os.replace(temporary, destination)
    finally:
        Path(temporary).unlink(missing_ok=True)
    return {"entries": count, "epoch": epoch, "class_epoch": epoch + 2}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    parser.add_argument("destination", type=Path)
    parser.add_argument("--epoch", type=int, default=315532800)
    args = parser.parse_args()
    print(json.dumps(normalize(args.source, args.destination, args.epoch)))


if __name__ == "__main__":
    main()
